def evaluate_draft(content_bundle, claim_graph, policy_engine):
    # Rejecting the obvious path: an LLM-as-a-judge cannot legally indemnify a FINRA or MLR violation.
    # Step 1: Invert review by forcing generation to declare claim origins rather than scanning for them.
    atoms = content_bundle.extract_asserted_propositions()

    # Semantic similarity is not legal substantiation; require explicit pointer to approved source ledger.
    unanchored_claims = [c for c in atoms if not claim_graph.has_certified_edge(c.id, c.citation_id)]
    if unanchored_claims:
        return ROUTE_TO_LEGAL_QUEUE(content_bundle, reason="unsubstantiated_claim", unanchored_claims)

    # Ad tech strips metadata like C2PA downstream, so disclosure obligations must be baked into payload text/pixels.
    content_bundle = policy_engine.burn_in_statutory_disclosures(content_bundle, market=content_bundle.geo)

    # Brand alignment is subjective semantics; automate only negative criteria (hard prohibitions), never positive 'feel'.
    hard_breaches = policy_engine.scan_blacklisted_framings(content_bundle.rendered_output)
    if hard_breaches:
        return REJECT_TO_CREATOR(hard_breaches)

    # Since zero-shot clearance is currently impossible, throttle clearance entirely by blast radius and media spend.
    return route_by_risk_budget(content_bundle, risk_score=content_bundle.projected_reach * content_bundle.regulated_tier)

